  SHORT = { 8 => '\\b', 9 => '\\t', 10 => '\\n', 12 => '\\f', 13 => '\\r' }.freeze

  def canon(v)
    case v
    when nil then 'null'
    when true then 'true'
    when false then 'false'
    when Integer then v.to_s
    when String
      o = +'"'
      v.each_char do |ch|
        c = ch.ord
        if ch == '"' then o << '\\"'
        elsif ch == '\\' then o << '\\\\'
        elsif SHORT.key?(c) then o << SHORT[c]
        elsif c < 0x20 then o << format('\\u%04x', c)
        else o << ch
        end
      end
      o << '"'
    when Array then "[#{v.map { |x| canon(x) }.join(',')}]"
    when Hash then "{#{v.keys.sort_by(&:b).map { |k| "#{canon(k)}:#{canon(v[k])}" }.join(',')}}"
    else raise "canon: unsupported #{v.class}"
    end
  end

  def b64(b) = Base64.urlsafe_encode64(b, padding: false)
  def hash_canon(v) = b64(Digest::SHA256.digest(canon(v)))
  def goal_digest(g) = hash_canon({ 'd' => 'atlas-pca/goal-ir/v1', 'goal' => g })
  def digest(kind, v) = b64(Digest::SHA256.digest("pca-goal:v1:#{kind}:#{canon(v)}"))

  def k_not(a) = 2 - a
  def b2k(b) = b ? 2 : 0
  def same_unit(a, b) = canon(a) == canon(b)

  def eq_v(x, y)
    case x['k']
    when 'q' then y['k'] == 'q' && same_unit(x['q']['u'], y['q']['u']) ? b2k(x['q']['n'] == y['q']['n']) : 1
    when 's' then y['k'] == 's' ? b2k(x['s'] == y['s']) : 1
    else 1
    end
  end

  def lt_v(x, y) = x['k'] == 'q' && y['k'] == 'q' && same_unit(x['q']['u'], y['q']['u']) ? b2k(x['q']['n'] < y['q']['n']) : 1

  def cmp_(op, x, y)
    return 1 if x.nil? || y.nil?

    case op
    when 'eq' then eq_v(x, y)
    when 'ne' then k_not(eq_v(x, y))
    when 'lt' then lt_v(x, y)
    when 'gte' then k_not(lt_v(x, y))
    when 'gt' then lt_v(y, x)
    when 'lte' then k_not(lt_v(y, x))
    else
      t = 1
      if y['k'] == 'set'
        t = 0
        y['items'].each { |it| t = [t, eq_v(x, it)].max }
      end
      op == 'in' ? t : k_not(t)
    end
  end

  def term(t, a, h)
    case t['k']
    when 'param' then a['params'][t['path']]
    when 'lit' then t['v']
    else
      q = h['aggs'][t['bid']]
      q.nil? ? nil : { 'k' => 'q', 'q' => q }
    end
  end

  def cond(c, a, h)
    case c['k']
    when 'true' then 2
    when 'cmp' then cmp_(c['op'], term(c['l'], a, h), term(c['r'], a, h))
    when 'and' then [cond(c['a'], a, h), cond(c['b'], a, h)].min
    when 'or' then [cond(c['a'], a, h), cond(c['b'], a, h)].max
    else k_not(cond(c['c'], a, h))
    end
  end

  def part_ids(o, p)
    return [p['id']] if p['k'] == 'exact'
    return p['ids'] if p['k'] == 'oneof'

    r = o['rels'].find { |x| x['rel'] == p['rel'] && x['anchor'] == p['anchor'] }
    r ? r['members'] : []
  end

  def resolve(o, s)
    return nil if s['k'] == 'any'
    return part_ids(o, s) unless s['k'] == 'all_of'

    acc = nil
    s['parts'].reverse_each do |p|
      ids = part_ids(o, p)
      acc = acc.nil? ? ids : ids.select { |i| acc.include?(i) }
    end
    acc
  end

  def res_ok(p, r) = p.nil? || p.include?(r)
  def verbs_of_class(o, cls) = o['verbs'].select { |v| v['cls'] == cls }.map { |v| v['verb'] }
  def proh_verbs(o, p) = p['target']['k'] == 'verb' ? [p['target']['verb']] : verbs_of_class(o, p['target']['cls'])
  def lsel(o, b) = b['sel']['k'] == 'gids' ? [b['sel']['gids'], []] : [[], verbs_of_class(o, b['sel']['cls'])]
  def applies(s, gid, verb) = s[0].include?(gid) || s[1].include?(verb)

  def in_scope(b, a, x)
    s = b['scope']
    case s['k']
    when 'session' then a['sess'] == x['sess']
    when 'principal' then a['prin'] == x['prin']
    when 'org' then a['org'] == x['org']
    else s['agents'].include?(a['agent']) && s['agents'].include?(x['agent'])
    end
  end

  def in_window(w, a, x)
    case w['k']
    when 'sliding' then a['t'] - w['ms'] < x['t'] && x['t'] <= a['t']
    when 'period' then w['ms'].positive? && (a['t'] - w['t0']).div(w['ms']) == (x['t'] - w['t0']).div(w['ms'])
    else true
    end
  end

  def exceeded(b, s, a, h)
    items = h['adms'].select { |m| applies(s, m['gid'], m['act']['verb']) && in_scope(b, a, m['act']) && in_window(b['window'], a, m['act']) }.map { |m| m['act'] } + [a]
    return b2k(items.length > b['cap']['n']) if b['agg'] == 'count'

    if b['agg'] == 'distinct'
      vs = {}
      items.each do |x|
        return 1 unless x['params'].key?(b['key'])

        vs[canon(x['params'][b['key']])] = true
      end
      return b2k(vs.length > b['cap']['n'])
    end
    ns = []
    items.each do |x|
      v = term(b['value'], x, h)
      return 1 if v.nil? || v['k'] != 'q' || !same_unit(v['q']['u'], b['cap']['u'])

      ns << v['q']['n']
    end
    b2k((b['agg'] == 'sum' ? ns.sum : ns.max) > b['cap']['n'])
  end

  def bound_dec(b, s, a, h)
    e = exceeded(b, s, a, h)
    e == 2 ? (b['onExceed'] == 'deny' ? 0 : 1) : (e == 1 ? 1 : 2)
  end

  def strip(g)
    g.merge('holes' => [], 'grants' => g['grants'].reject { |x| g['holes'].any? { |h| h['global'] || h['affects'].include?(x['gid']) } })
  end

  def grant_dec(g, o, gr, a, h)
    deleg_ok = a['depth'].zero? || g['deleg']['mayTouch'].include?(gr['gid'])
    m = [b2k(a['verb'] == gr['verb'] && deleg_ok), b2k(res_ok(resolve(o, gr['res']), a['res'])), cond(gr['cond'], a, h)].min
    g['bounds'].each do |b|
      s = lsel(o, b)
      m = [m, bound_dec(b, s, a, h)].min if applies(s, gr['gid'], a['verb'])
    end
    m
  end

  def decide(goal, o, a, h)
    g = strip(goal)
    v = g['validity']
    d = 2
    if a['t'] < v['notBefore'] || a['t'] > v['notAfter'] then d = 0
    elsif v['maxIdle'].positive? && h['last'] >= 0 && a['t'] - h['last'] > v['maxIdle'] then d = 0
    elsif a['depth'].negative? || a['depth'] > g['deleg']['maxDepth'] then d = 0
    end
    g['prohibits'].each do |p|
      m = [b2k(proh_verbs(o, p).include?(a['verb'])), b2k(res_ok(resolve(o, p['res']), a['res'])), cond(p['cond'], a, h)].min
      d = [d, m == 2 ? 0 : (m == 1 ? 1 : 2)].min
    end
    g['escalateOn'].each { |c| d = [d, cond(c, a, h).zero? ? 2 : 1].min }
    per = g['grants'].map { |gr| grant_dec(g, o, gr, a, h) }
    d = [d, per.empty? ? 0 : per.max].min
    return { 'decision' => d == 1 ? 'escalate' : 'deny', 'witness' => nil } if d != 2

    gr = g['grants'][per.index(2)]
    { 'decision' => 'allow', 'witness' => { 'gid' => gr['gid'], 'bids' => g['bounds'].select { |b| applies(lsel(o, b), gr['gid'], a['verb']) }.map { |b| b['bid'] } } }
  end

  NEG = { 'eq' => 'ne', 'ne' => 'eq', 'lt' => 'gte', 'gte' => 'lt', 'gt' => 'lte', 'lte' => 'gt', 'in' => 'nin', 'nin' => 'in' }.freeze

  def nnf(c, pos)
    case c['k']
    when 'true' then { 'k' => pos ? 'true' : 'false' }
    when 'cmp' then { 'k' => 'atom', 'op' => pos ? c['op'] : NEG[c['op']], 'l' => c['l'], 'r' => c['r'] }
    when 'and' then { 'k' => pos ? 'and' : 'or', 'a' => nnf(c['a'], pos), 'b' => nnf(c['b'], pos) }
    when 'or' then { 'k' => pos ? 'or' : 'and', 'a' => nnf(c['a'], pos), 'b' => nnf(c['b'], pos) }
    else nnf(c['c'], !pos)
    end
  end

  def pat(p) = p.nil? ? { 'k' => 'star' } : { 'k' => 'set', 'ids' => p }

  def lower(o, goal)
    g = strip(goal)
    ceils = g['bounds'].map do |b|
      s = lsel(o, b)
      { 'bid' => b['bid'], 'selGids' => s[0], 'selVerbs' => s[1], 'agg' => b['agg'], 'value' => b['value'], 'key' => b['key'], 'window' => b['window'], 'scope' => b['scope'], 'cap' => b['cap'], 'onExceed' => b['onExceed'] }
    end
    { 'preds' => g['grants'].map { |x| { 'gid' => x['gid'], 'verb' => x['verb'], 'res' => pat(resolve(o, x['res'])), 'cond' => nnf(x['cond'], true) } },
      'prohs' => g['prohibits'].map { |p| { 'pid' => p['pid'], 'verbs' => proh_verbs(o, p), 'res' => pat(resolve(o, p['res'])), 'cond' => nnf(p['cond'], true) } },
      'ceils' => ceils, 'escs' => g['escalateOn'].map { |c| nnf(c, true) }, 'validity' => g['validity'], 'deleg' => g['deleg'] }
  end

  # ---- selector expansion (pca-goal selectors.ts / formal/dafny/GoalSelect.dfy)
  # An unconfirmed verb carries pca.unreviewed (it is the top of the registry): a class ALLOW never covers it (float = false), a class PROHIBITION or bound over a trait selector ALWAYS covers it, whatever all_of and none_of say (float = true).
  def class_verbs(cat, all_of, none_of, float)
    cat['verbs'].select do |v|
      ts = v['traits']
      if float then ts.include?('pca.unreviewed') || (all_of.all? { |t| ts.include?(t) } && none_of.none? { |t| ts.include?(t) })
      else all_of.all? { |t| ts.include?(t) } && (none_of + ['pca.unreviewed']).none? { |t| ts.include?(t) }
      end
    end.map { |v| v['verb'] }
  end

  def resolve_role(ont, cat, verb, role)
    info = cat['verbs'].find { |v| v['verb'] == verb }
    decl = ont['verbs'].find { |v| v['verb'] == verb }
    return nil if info.nil? || decl.nil?

    paths = info['roles'][role] || []
    return nil unless paths.length == 1

    p = decl['params'].find { |x| x['path'] == paths[0] }
    p && [p['path'], p['ty']]
  end

  def x_term(ont, cat, verb, t)
    return t unless t['k'] == 'role'

    r = resolve_role(ont, cat, verb, t['role'])
    r && { 'k' => 'param', 'path' => r[0], 'ty' => r[1] }
  end

  def x_cond(ont, cat, verb, c)
    case c['k']
    when 'true' then { 'k' => 'true' }
    when 'cmp'
      l = x_term(ont, cat, verb, c['l'])
      r = x_term(ont, cat, verb, c['r'])
      l && r && { 'k' => 'cmp', 'op' => c['op'], 'l' => l, 'r' => r }
    when 'and', 'or'
      a = x_cond(ont, cat, verb, c['a'])
      b = x_cond(ont, cat, verb, c['b'])
      a && b && { 'k' => c['k'], 'a' => a, 'b' => b }
    else
      a = x_cond(ont, cat, verb, c['c'])
      a && { 'k' => 'not', 'c' => a }
    end
  end

  def bound_value(ont, cat, vs, t)
    return t unless t['k'] == 'role'

    rs = []
    vs.each do |v|
      r = resolve_role(ont, cat, v, t['role'])
      return nil if r.nil?

      rs << r
    end
    return nil if rs.empty?

    return { 'k' => 'param', 'path' => rs[0][0], 'ty' => rs[0][1] } if rs.all? { |r| r[0] == rs[0][0] && canon(r[1]) == canon(rs[0][1]) }
    return { 'k' => 'param', 'path' => "@#{t['role']}", 'ty' => rs[0][1] } if rs.all? { |r| canon(r[1]) == canon(rs[0][1]) }

    nil
  end

  def expand_sel(sg, ont, cat)
    es = []
    sg['grants'].each do |gr|
      s = gr['sel']
      verbs = s['k'] == 'verb' ? [s['verb']] : class_verbs(cat, s['all_of'], s['none_of'], false)
      verbs.each do |v|
        c = x_cond(ont, cat, v, gr['cond'])
        next if c.nil?

        es << [gr['gid'], { 'gid' => s['k'] == 'class' ? "#{gr['gid']}.#{v}" : gr['gid'], 'verb' => v, 'res' => gr['res'], 'cond' => c }]
      end
    end
    ids_of = ->(srcs) { es.select { |e| srcs.include?(e[0]) }.map { |e| e[1]['gid'] } }
    gids_of_verbs = ->(vs) { es.select { |e| vs.include?(e[1]['verb']) }.map { |e| e[1]['gid'] } }
    verbs_of_gids = ->(g) { es.select { |e| g.include?(e[1]['gid']) }.map { |e| e[1]['verb'] } }
    prohibits = []
    sg['prohibits'].each do |p|
      t = p['target']
      verbs = t['k'] == 'verb' ? [t['verb']] : (t['k'] == 'effect' ? verbs_of_class(ont, t['cls']) : class_verbs(cat, t['all_of'], t['none_of'], true))
      verbs.each do |v|
        c = x_cond(ont, cat, v, p['cond']) || { 'k' => 'true' }
        prohibits << { 'pid' => t['k'] == 'verb' ? p['pid'] : "#{p['pid']}.#{v}", 'target' => { 'k' => 'verb', 'verb' => v }, 'res' => p['res'], 'cond' => c }
      end
    end
    bounds = []
    sg['bounds'].each do |b|
      s = b['sel']
      if s['k'] == 'gids'
        gids = ids_of.call(s['gids'])
        rv = verbs_of_gids.call(gids)
      elsif s['k'] == 'effect'
        gids = nil
        rv = verbs_of_class(ont, s['cls'])
      else
        gids = gids_of_verbs.call(class_verbs(cat, s['all_of'], s['none_of'], true))
        rv = verbs_of_gids.call(gids)
      end
      val = bound_value(ont, cat, rv, b['value'])
      next if val.nil? || (!gids.nil? && gids.empty?)

      sel = gids.nil? ? { 'k' => 'effect', 'cls' => s['cls'] } : { 'k' => 'gids', 'gids' => gids }
      bounds << { 'bid' => b['bid'], 'sel' => sel, 'agg' => b['agg'], 'value' => val, 'key' => b['key'], 'window' => b['window'], 'scope' => b['scope'], 'cap' => b['cap'], 'onExceed' => b['onExceed'] }
    end
    { 'v' => 1, 'principal' => sg['principal'], 'ontDigest' => sg['ontDigest'], 'nlDigest' => sg['nlDigest'], 'sources' => sg['sources'],
      'grants' => es.map { |e| e[1] }, 'prohibits' => prohibits, 'bounds' => bounds, 'validity' => sg['validity'],
      'deleg' => sg['deleg'].merge('mayTouch' => ids_of.call(sg['deleg']['mayTouch'])), 'escalateOn' => sg['escalateOn'],
      'wildcardAck' => ids_of.call(sg['wildcardAck']), 'holes' => sg['holes'].map { |h| h.merge('affects' => ids_of.call(h['affects'])) } }
  end

  RANK = { 'deny' => 0, 'escalate' => 1, 'allow' => 2 }.freeze
  def meet(d, s) = RANK.key?(s) && RANK[s] < RANK[d] ? s : d

  def polarity(ws)
    out = {}
    walk = lambda do |c|
      case c['k']
      when 'and', 'or' then walk.call(c['a']); walk.call(c['b'])
      when 'not' then walk.call(c['c'])
      when 'cmp'
        [c['l'], c['r']].each do |t|
          out[t['path']] = true if t['k'] == 'param' && %w[env.class. env.prov. env.judge. env.world.].any? { |p| t['path'].start_with?(p) }
        end
      end
    end
    ws.each { |w| walk.call(w) }
    out.keys.sort_by(&:b)
  end

  def units(schema, terms) = terms.keys.select { |p| !schema.key?(p) || canon(schema[p]) != canon(terms[p]) }.sort_by(&:b)

  def pep(d, ctx, ans)
    return true if d == 'allow'
    return false if d == 'deny'

    !ans.nil? && ans['valid'] == true && %w[policy_digest action_digest history_head].all? { |k| ans[k] == ctx[k] }
  end

  def commit(g, p, s) = b64(Digest::SHA256.digest("pca-goal:v3:commit:#{g}:#{p}:#{s}"))

  def run_fn(v)
    i = v['input']
    case v['fn']
    when 'canon' then { 'canon' => canon(i), 'digest' => goal_digest(i) }
    when 'units' then units(i['schema'], i['terms'])
    when 'polarity' then polarity(i)
    when 'meet' then meet(i['decision'], i['signal'])
    when 'pep' then pep(i['decision'], i['ctx'], i['answer'])
    when 'commit' then { 'commit' => commit(i['goal_digest'], i['policy_digest'], i['salt']), 'opens_other_goal' => false }
    when 'claim' then !i['replayed_ppm'].nil? && i['replayed_ppm'] < i['min_ppm'] ? meet(i['base'], 'escalate') : i['base']
    else raise "unknown fn #{v['fn']}"
    end
  end

  # Replays every vector of a directory: [vectors, probes, disagreements].
  def replay(d)
    bad = []
    n = probes = 0
    Dir.children(d).sort.each do |f|
      next if f == 'index.json' || !f.end_with?('.json')

      v = JSON.parse(File.read(File.join(d, f), encoding: 'UTF-8'))
      n += 1
      if v['kind'] == 'fn'
        bad << v['id'] if canon(run_fn(v)) != canon(v['expect'])
        next
      end
      bad << "#{v['id']}:expansion" if v['sel'] && canon(expand_sel(v['sel']['goal'], v['ontology'], v['sel']['catalog'])) != canon(v['goal'])
      bad << "#{v['id']}:goal_digest" if goal_digest(v['goal']) != v['goal_digest']
      next unless v['compile']['ok']

      bad << "#{v['id']}:policy_digest" if hash_canon(lower(v['ontology'], v['goal'])) != v['policy_digest']
      v['probes'].each_with_index do |p, i|
        probes += 1
        bad << "#{v['id']}##{i}" if canon(decide(v['goal'], v['ontology'], p['action'], p['history'])) != canon(p['expect'])
      end
    end
    [n, probes, bad]
  end
end

if $PROGRAM_NAME == __FILE__
  n, probes, bad = G.replay(ARGV[0])
  puts "ruby: #{n} vectors, #{probes} probes, #{bad.length} disagreements"
  bad.first(20).each { |b| puts "   #{b}" }
  exit(bad.empty? && n.positive? ? 0 : 1)
end
